const groupTotals = `-- name: GroupTotals :one
SELECT CAST(COUNT(*) AS INTEGER) AS contracts,
  CAST(COALESCE(SUM(value), 0) AS INTEGER) AS value,
  CAST(COALESCE(SUM(CASE WHEN method = 'limited' THEN value END), 0) AS INTEGER) AS limited_value,
  CAST(COALESCE(SUM(CASE WHEN method = 'limited' THEN 1 END), 0) AS INTEGER) AS limited_contracts,
  CAST(COALESCE(MIN(published_date), '') AS TEXT) AS first_published,
  CAST(COALESCE(MAX(published_date), '') AS TEXT) AS last_published
FROM contract WHERE supplier_id IN (SELECT supplier_id FROM supplier_group_member WHERE group_id = ?)
`

type GroupTotalsRow struct {
	Contracts        int64
	Value            int64
	LimitedValue     int64
	LimitedContracts int64
	FirstPublished   string
	LastPublished    string
}

func (q *Queries) GroupTotals(ctx context.Context, groupID int64) (GroupTotalsRow, error) {
	row := q.db.QueryRowContext(ctx, groupTotals, groupID)
	var i GroupTotalsRow
	err := row.Scan(
		&i.Contracts,
		&i.Value,
		&i.LimitedValue,
		&i.LimitedContracts,
		&i.FirstPublished,
		&i.LastPublished,
	)
	return i, err
}

const groupYear = `-- name: GroupYear :one
SELECT CAST(COUNT(DISTINCT c.cn_id) AS INTEGER) AS contracts,
  CAST(COALESCE(SUM(cf.amount), 0) AS INTEGER) AS amount
FROM contract_fy cf
JOIN contract c ON c.cn_id = cf.cn_id
JOIN agency a ON a.id = c.agency_id
WHERE cf.fiscal_year = ?1 AND a.entity_id IS NOT NULL
  AND c.supplier_id IN (SELECT supplier_id FROM supplier_group_member WHERE group_id = ?2)
  AND c.supplier_id NOT IN (SELECT supplier_id FROM supplier_individual)
`

type GroupYearParams struct {
	Fy      string
	GroupID int64
}

type GroupYearRow struct {
	Contracts int64
	Amount    int64
}

// A corporate group's contract value falling in a year, counted as
// TopSupplierGroups counts it.
func (q *Queries) GroupYear(ctx context.Context, arg GroupYearParams) (GroupYearRow, error) {
	row := q.db.QueryRowContext(ctx, groupYear, arg.Fy, arg.GroupID)
	var i GroupYearRow
	err := row.Scan(&i.Contracts, &i.Amount)
	return i, err
}

