const kindTotals = `-- name: KindTotals :many
SELECT pe.expense_kind,
  CAST(COALESCE(SUM(CASE WHEN pe.fiscal_year = ?1 THEN pe.amount END), 0) AS INTEGER) AS cur
FROM program_expense pe
JOIN program p ON p.id = pe.program_id
WHERE pe.source_document_id = ?2 AND p.entity_id = ?3 AND pe.treatment = 'expense'
GROUP BY pe.expense_kind
ORDER BY cur DESC
`

type KindTotalsParams struct {
	Fy       string
	DocID    int64
	EntityID int64
}

type KindTotalsRow struct {
	ExpenseKind string
	Cur         int64
}

// Administered / departmental / corporate split for an entity.
func (q *Queries) KindTotals(ctx context.Context, arg KindTotalsParams) ([]KindTotalsRow, error) {
	rows, err := q.db.QueryContext(ctx, kindTotals, arg.Fy, arg.DocID, arg.EntityID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []KindTotalsRow
	for rows.Next() {
		var i KindTotalsRow
		if err := rows.Scan(&i.ExpenseKind, &i.Cur); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

